// The status values are schema.json's planStatus; links are http(s) or empty.
// The learner sees the plan's title and links, so a save rings their doorbell.
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const planId = String(Inputs.planId || '');
    const plans = planId ? await R.query('Plan', { objectId: { equalTo: planId } }, { limit: 2, plain: true }) : [];
    if (plans.length !== 1) return refuse('That plan is no longer there. Reload the page.');
    const title = String(Inputs.title || '').trim().replace(/\s+/g, ' ');
    if (!title) return refuse('Give the plan a title.');
    if (title.length > 140) return refuse('Keep the title under 140 characters.');
    const status = String(Inputs.status || plans[0].status || 'active');
    if (!['active', 'paused', 'finished'].includes(status)) return refuse('A plan is active, paused or finished.');
    const link = (v, what) => {
      const s = String(v || '').trim();
      if (!s) return '';
      let u = null;
      try { u = new URL(s); } catch (e) { u = null; }
      return u && (u.protocol === 'https:' || u.protocol === 'http:') ? u.href : refuse('The ' + what + ' is not a web address. Links start with https://');
    };
    const meetingLink = link(Inputs.meetingLink, 'meeting link');
    if (meetingLink === undefined) return;
    const bookingLink = link(Inputs.bookingLink, 'booking link');
    if (bookingLink === undefined) return;
    await R.save(planId, { title, status, meetingLink, bookingLink }, { className: 'Plan' });
    const learner = plans[0].learner;
    await R.create('Doorbell', { learner, topic: 'plan' }, { acl: { [learner]: { read: true }, 'role:staff': { read: true } } });
    Outputs.done();
  } catch (e) {
    console.error('[dbu:savePlan]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
